    twisty.textContent = "▼";
    row.appendChild(twisty);
    row.appendChild(thumbnailEl(holon, 16));
    const name = document.createElement("span");
    name.className = "nclass";
    name.textContent = classNameOf(holon);
    row.appendChild(name);
